// ══════════════════════════════════════════════════════════════
//  ⚙️  แก้บรรทัดนี้ที่เดียว แล้วต่อกับ Google Sheet ได้เลย
// ══════════════════════════════════════════════════════════════
const SHEET_ID = 'PASTE_YOUR_GOOGLE_SHEET_ID';   // ใช้ Sheet ID เดียวกับ workflow หลัก (น้องอิ่มใจ)
// ══════════════════════════════════════════════════════════════

const item = $input.first();
const body = item.json.body || {};

const customer_name = (body.customer_name || '').toString().trim();
const phone = (body.phone || '').toString().trim();
const items = (body.items || '').toString().trim();
const order_type = body.order_type === 'delivery' ? 'delivery' : 'pickup';
const total = Number(body.total) || 0;
const note = (body.note || '').toString().trim();
const line_user_id = (body.line_user_id || '').toString().trim();

const missing = [];
if (!customer_name) missing.push('customer_name');
if (!phone) missing.push('phone');
if (!items) missing.push('items');
if (!(total > 0)) missing.push('total');

// เวลาไทย (UTC+7) โดยไม่พึ่ง timezone ของเครื่อง n8n
const bkk = new Date(Date.now() + 7 * 3600 * 1000);
const pad = (n) => String(n).padStart(2, '0');
const ymd = `${bkk.getUTCFullYear()}${pad(bkk.getUTCMonth() + 1)}${pad(bkk.getUTCDate())}`;
const hms = `${pad(bkk.getUTCHours())}${pad(bkk.getUTCMinutes())}${pad(bkk.getUTCSeconds())}`;
const created_at = `${bkk.getUTCFullYear()}-${pad(bkk.getUTCMonth() + 1)}-${pad(bkk.getUTCDate())} ${pad(bkk.getUTCHours())}:${pad(bkk.getUTCMinutes())}:${pad(bkk.getUTCSeconds())}`;
const etaDate = new Date(bkk.getTime() + 20 * 60000);
const eta = `${pad(etaDate.getUTCHours())}:${pad(etaDate.getUTCMinutes())}`;

return [{
  json: {
    valid: missing.length === 0,
    error: missing.length ? `ข้อมูลไม่ครบ: ${missing.join(', ')}` : '',
    sheet_id: SHEET_ID,
    order_id: `ORD-${ymd}-${hms}`,
    created_at,
    line_user_id,
    customer_name,
    phone,
    items,
    total,
    order_type,
    status: 'รับออเดอร์แล้ว',
    eta,
    note,
  }
}];

// ══════════════════════════════════════════════════════════════
//  ⚙️  แก้บรรทัดนี้ที่เดียว แล้วต่อกับ Google Sheet ได้เลย
// ══════════════════════════════════════════════════════════════
const SHEET_ID = 'PASTE_YOUR_GOOGLE_SHEET_ID';   // ใช้ Sheet ID เดียวกับ workflow หลัก (น้องอิ่มใจ)
// ══════════════════════════════════════════════════════════════

const item = $input.first();
const order_id = (item.json.query?.order_id || '').toString().trim();

return [{ json: { sheet_id: SHEET_ID, order_id } }];

// ══════════════════════════════════════════════════════════════
//  ⚙️  แก้บรรทัดนี้ที่เดียว แล้วต่อกับ Google Sheet ได้เลย
// ══════════════════════════════════════════════════════════════
const SHEET_ID = 'PASTE_YOUR_GOOGLE_SHEET_ID';   // ใช้ Sheet ID เดียวกับ workflow หลัก (น้องอิ่มใจ)
// ══════════════════════════════════════════════════════════════

const item = $input.first();
const line_user_id = (item.json.query?.line_user_id || '').toString().trim();

return [{ json: { sheet_id: SHEET_ID, line_user_id, valid: line_user_id.length > 0 } }];

const orders = $input.all()
  .map((item) => item.json)
  .filter((o) => o.order_id)
  .sort((a, b) => (a.created_at < b.created_at ? 1 : -1));

return [{ json: { result: 'ok', orders } }];

// ══════════════════════════════════════════════════════════════
//  ⚙️  แก้บรรทัดนี้ที่เดียว แล้วข้อความจากฟอร์ม "ติดต่อเรา" จะเด้งเข้า Discord
// ══════════════════════════════════════════════════════════════
const DISCORD_WEBHOOK = 'PASTE_YOUR_DISCORD_WEBHOOK_URL';   // อันเดียวกับ workflow หลักก็ได้ หรือแยกช่องก็ได้
// ══════════════════════════════════════════════════════════════

const item = $input.first();
const body = item.json.body || {};

const name = (body.name || '').toString().trim();
const contact = (body.contact || '').toString().trim();
const message = (body.message || '').toString().trim();

const missing = [];
if (!name) missing.push('name');
if (!contact) missing.push('contact');
if (!message) missing.push('message');

return [{
  json: {
    valid: missing.length === 0,
    error: missing.length ? `ข้อมูลไม่ครบ: ${missing.join(', ')}` : '',
    discord_webhook: DISCORD_WEBHOOK,
    name, contact, message,
  }
}];

